//! The verifier's prompts, copied character for character from verification.py's literals: a request differing
//! from Python's by one byte is a replay miss.

use fastbrowse_core::models::UNTRUSTED;

pub(super) const REACHED: &str = "When the requested outcome is to open or reach a page, that destination must be showing now. An earlier visit followed by Back does not satisfy it. An executed click proves only the interaction, not that its destination loaded; an HTTP error is not a successful visit. For a search or filter, set fields and executed clicks do not prove the resulting content loaded. Require current matching results or an explicit empty-result state, not a pending search or loading view. A starting address or an intermediate visit in a longer task may be evidenced by the visited addresses, the first of which is where the run began; it does not have to remain open.";

pub(super) const UNGROUNDED: &str = "Requirement ids whose facts were read from a page that is not the one the task described: a summary, preview or default listing reached by a guessed address, or a page that does not show the task's own query, filters, dates, sort or category in force. Name one here even when it has evidence, because the evidence is from the wrong page.";

pub(super) fn complete() -> String {
    format!(
        "{UNTRUSTED}\nDoes the page or the notes visibly confirm completion of the task in state? Requested run_reports are copied from browser state and the action record after completion; they do not need page quotes or a written answer yet. Be strict: a matching link, a filled but unsubmitted form, or a partial result is not done. For comparisons, require the requested constraints and ordering or a comparison of all matching results. A highlighted result or query preview alone is insufficient."
    )
}

pub(super) fn unmet_action(requirement_text: &str) -> String {
    format!(
        "{UNTRUSTED}\nIs this requirement not visibly satisfied? The actions in state are the run's own record; a requirement that orders actions is satisfied only when they show that order. {REACHED}\n\n{requirement_text}"
    )
}

pub(super) fn unmet_information(requirement_text: &str) -> String {
    format!(
        "{UNTRUSTED}\nDo the notes lack the facts this requirement needs? A comparison or conclusion needs every fact it is drawn from, for the right entities; the conclusion itself need not be written.\n\n{requirement_text}"
    )
}

pub(super) fn draft_needs_writing() -> String {
    format!(
        "{UNTRUSTED}\nDoes the draft in state need rewriting before it answers the task? It does if it misses part of what was asked, repeats or contradicts itself, includes unrelated facts, leaves a comparison, count or calculation undone, or gives a value without saying which part of the task it answers when that is not plain. A short quoted value or labelled field can answer as written; it does not need a full sentence. A comparison that states its result can include the values it compared. These are supporting facts, not unrelated ones. Judge the requested answer: when a task asks to perform actions and report a fact, the answer need only report that fact, not recap each action. Completion of the actions is checked separately. Requested run_reports are appended by code from browser state and the action record, so their absence from this page-fact draft is not an omission."
    )
}

pub(super) fn verdict(evidence: &str) -> String {
    format!(
        "## Verdict\nDecide from {evidence} whether the task is finished. Be strict and name every requirement id that is not visibly satisfied. An action requirement (clicking a link or button, filling a field, submitting a form, navigating) is satisfied when the steps taken show it executed on the control the task meant and produced the requested outcome. The task may paraphrase the control's label; the acted-on control is its equivalent when the page offered no closer match, which is the match the agent made when it acted. The steps are the run's own record, and a click that navigated is not visible on the page it left. Be strict about whether the action happened, not about the task's wording of the label. A requirement that orders actions (enter one value, then go back and change it) is satisfied only when the steps show that order. {REACHED} A date relative to today is judged against the current date. A requirement to compare, count or conclude from facts is satisfied when the notes hold those facts: the answer draws the conclusion, and no page shows it. A requirement to narrow a search or listing (a filter, option or sort) is satisfied when the page shows it applied, in a set control, the address or the page's own filter text, not when the rows in view happen to match it.\n\nThen judge where the facts came from. A page holding values of the right kind is not the page the task described unless it shows that task's own query, filters, dates, sort or category in force. A summary, preview, default or related listing can show prices or rows that are not the ones asked for. Name in ungrounded every requirement whose facts were read from such a page, even when it has evidence. An address this run built from the task can land on the wrong search: judge such a page by what it shows, not by how the run reached it. An answer states the terms a value was quoted under, such as what it covers and the dates it applies to."
    )
}

#[allow(clippy::too_many_arguments)]
pub(super) fn verify_user(
    task: &str,
    today: &str,
    requirements: &str,
    run_reports: &str,
    steps: &str,
    controls: &str,
    grounding: &str,
    visited: &str,
    url: &str,
) -> String {
    format!(
        "## Task\n{task}\n\n## Current date\n{today}\n\n## Requirements\n{requirements}\n\n## Run reports\n{run_reports}\nThese reports are copied from browser state and the action record after completion; they do not need page quotes or a written answer yet.\n\n## Steps taken\n{steps}\n\n## Set controls\n{controls}\n\n{grounding}{visited}## Page\n{url}\n"
    )
}

pub(super) const SHARED_NOTE: &str = " Cited sources and counterevidence use source_ref entries into shared_sources. Resolve every reference to its full source. Repeated references preserve each claim's own citation; record indices still index that claim's cited_sources in order. Check every claim and every source.";

pub(super) const STALE_REPAIR: &str = "Some cited facts are no longer current or collection records are missing. Use current source quotes and preserve their collection scope; do not cite superseded conclusions.";

pub(super) fn settled(criterion: &str) -> String {
    format!(
        "{UNTRUSTED} Does the actual answer satisfy this criterion completely, with every requested output explicitly stated and directly supported by its own cited sources? Judge every requested entity separately. Related items, implied values and ambiguous source associations do not satisfy it. A derived count or comparison can rest on the cited source records that support its calculation; the sources need not state the derived result. Observed page titles can reveal shortened exact strings but cannot replace a missing citation. Other quotes retained from the same pages are in counterevidence: they never support the answer, and when one conflicts with, qualifies or gives another value for a requested output, the answer does not satisfy the criterion. Criterion: {criterion}"
    )
}

pub(super) fn select(task: &str, criterion: &str) -> String {
    format!(
        "{UNTRUSTED} Select the claim that explicitly states the requested output for the correct entity. Preserve the original task's each-item and all-item scope. One item's value cannot discharge a field requested for several items. A truthful statement about another item does not report that field for the requested item. Select all only when the criterion needs multiple claims, and none when absent or only implied. Task: {task}\nCriterion: {criterion}"
    )
}

pub(super) fn identities() -> String {
    format!(
        "{UNTRUSTED} Resolve each requested output's subjects to literal identifying quotes. The answer declares which named entities correspond to its numbered results. It cannot supply identity evidence. For each criterion return scope entities and every requested subject's offered source_ref and exact identifying quote from its body or captured page title. Copy only the entity name or identifying description, not the reported field value. When a record's only identifier is itself a requested field, such as an order reference, quote that identifier for each of the record's outputs. Code-captured control context binds a quote to its actual hovered DOM ancestor and sibling position; it can identify a positional subject but cannot supply an absent quoted value. Do not infer identity from a URL, shared page, item count or a neighboring table column. A numbered subject must bind to the entity the answer actually labels with that number. Comparisons can require several subjects. Use scope subjectless only for a criterion with no individual entity identity to establish, such as answer format or an aggregate zero-record result. Missing identity evidence is scope unresolved, never subjectless. Do not change requested entities or omit subjects. List each distinct source_ref and literal identifying quote once in identities, each with a short unique id. Bind each criterion to every required subject through identity_ids. Scope entities requires at least one valid id; subjectless and unresolved have no ids."
    )
}

pub(super) const DATED: &str = " current_date is the run's own date, supplied by code rather than read from a page. Judge a criterion relative to today, such as the next Monday or the month after next, against it; the quoted value must still be on the page.";

pub(super) fn source_audit() -> String {
    format!(
        "{UNTRUSTED} Check source availability separately for each criterion. Judge whether its selected quoted sources provide every requested output value for the correct entity. Answer assertions are withheld and cannot fill missing source values. Return no when a requested value or its association with the entity is absent or ambiguous. Eligibility qualifiers identify the entity; unrelated fields need not appear in each field's quote. Entity ordinals label the compared answer entities, not search rankings, unless a ranking is explicitly requested by the task. The task defines scope, not evidence; criteria cannot add requirements the task did not ask for. Claim selection is provisional: independently prove the field belongs to each requested entity identified by its literal quote. A quote for one subject cannot answer another subject's field. A shared page, title, collection or total count does not bind a comparison-table column or related model to the requested subject. An explicitly labeled value remains available alongside an eligibility-dependent alternative; preserve those conditions rather than assuming one value supersedes the other. An explicit exhaustive description can establish that no other members exist; absence from a partial description cannot. An explicit empty-result quote can answer a request to find records with a finding of none within its stated scope. Missing or unread content cannot. A total alone does not provide a component breakdown. A value scoped to one component, mode, tier or single-item configuration does not establish an aggregate value or another configuration. Require the source scope to match the requested scope and preserve explicit distinctions. Do not add independent component maxima unless quoted sources state that they apply simultaneously and combine additively. An explicit aggregate rating need not equal their sum. Counterevidence contains other retained quotes from the same exact source address and frame. Check whether it conflicts with the requested value for the same literal entity and scope. Conflicting explicit values remain available as alternatives, not a single settled value; the assertion audit must require their conflict to be acknowledged. Unclear entity or scope associations make availability uncertain. Different entities or explicitly different configurations are not contradictions. Counterevidence cannot supply missing support or subject bindings for the selected quotes. A requested recommendation does not require the page to recommend anything: quoted facts can provide grounds for the answer's preference. A quoted property of one option can support a subjective preference. Do not require every compared option's values for a recommendation criterion merely because another task output compares options. The assertion audit separately requires all operands for any factual comparative advantage the answer claims. Control context identifies the quoted content's actual DOM container and sibling position, not an absent field value. Derived outputs can calculate from quoted records only when every operand and its association is explicit; the source need not state the conclusion literally. A quote marked complete_source contains the entire downloaded text file. This proves coverage of that file only, not a wider collection or missing operand associations. Counted-record metadata gives code-maintained distinct counts, their scope, cited record indices and collection completeness. A complete count can rest on its matching quoted records without a page stating the total. An incomplete or differently scoped count cannot establish the requested whole-list total. A count's standing, given for a claim that states a rank or order, ranks its group among all group_count groups code counted in that scope: rank is 1 plus the number of groups with a higher count, and tied is how many other groups share its count. groups lists the leading groups and those around this one, each with its own rank and code-maintained count; ranks between them are left out, not missing. When standing.complete is true, it establishes the group's rank and order without citing the other groups' records. When it is false, no rank is established. A count without a standing establishes no rank. pages_read lists every read code made of the collection, in order, including reads with no matching record; one url_ref can appear in several reads when the list loads more or pages in place at one address. A listed read with no cited record was read and held no match, so it is not missing coverage. Compared-record metadata preserves the reader's collection scope, completeness and indices into these cited sources. A complete comparison establishes coverage of that scope, not missing values, operand associations or the correctness of a conclusion. An incomplete comparison cannot establish a whole-list winner or absence. An absence can be derived from a complete collection only when its quoted context identifies the collection and every cited member includes the identity and fields needed to exclude a match. Check every member. Coverage alone does not prove that none match, and establishes nothing outside that scope. The quoted records must still identify matching entities and filters. Observed page titles provide identity context, not missing field evidence. Never reconstruct missing table column labels from prior knowledge. Return yes/no/uncertain per field and explain missing source values."
    )
}

pub(super) fn assertion_audit() -> String {
    format!(
        "{UNTRUSTED} Judge each requested output independently. First determine its value from each selected claim's cited quotes alone, without using the reported claim or prior knowledge to fill missing subject associations. Literal requested-entity quotes identify the subjects, but their URL alone does not bind a field in a related model's table column. Never transfer a field value from one subject to another. Determine the evidenced value without filling missing information. Then check that the claim explicitly states that value for the correct requested entity in the actual answer. Missing fields, unsupported component breakdowns, incomplete exact strings, ambiguous sources and claims for another entity fail. Eligibility qualifiers identify the entity and are checked across the answer, not demanded in every individual quote. Entity ordinals label compared answer entities, not search rankings unless explicitly requested by the task. The task defines scope, not evidence; do not add requirements beyond it. Preserve explicitly stated conditions on alternative values; do not assume an eligibility-dependent alternative supersedes an unrestricted value. An explicit exhaustive description can establish absence of other members. A quoted empty-result message supports reporting no records within that page's scope, not an unbounded claim that none exist elsewhere. Missing or unread content cannot prove absence. A total alone does not evidence a component breakdown. A value scoped to one component, mode, tier or single-item configuration does not establish an aggregate value or another configuration. Preserve the quoted scope and explicit distinctions in every assertion. Do not add independent component maxima unless quoted sources state that they apply simultaneously and combine additively. An explicit aggregate rating need not equal their sum. Other retained quotes are supplied as counterevidence only: they cannot support an assertion whose own citations do not support it. A conflicting value for the same literal entity and scope must be acknowledged with both values and their quoted conditions, or fail. Do not treat different entities or explicitly different configurations as contradictions. Derived outputs can calculate from quoted records only when every operand and its association is explicit. A quote marked complete_source contains the entire downloaded text file and establishes coverage of that file only. Partial excerpts and truncated downloads do not establish whole-file totals. Control context binds quoted content to its actual DOM container and sibling position, but cannot replace a missing quoted value. Counted-record metadata supplies code-maintained counts and collection completeness, with indices into that claim's cited sources. Check the reported count against that matching scope and quoted record membership. An incomplete count cannot establish a whole-list total. Check a reported rank or order by count against the count's standing, code's ranking of every group counted in that scope, and its tied count for a shared rank; it holds only when standing.complete is true, and a count without a standing establishes no rank. pages_read lists every read code made of the collection, in order; one address can be read in several states, and a listed read with no cited record was read and held no match. Compared-record metadata preserves the reader's collection scope, completeness and cited source indices. Check the conclusion against every compared operand and the matching scope. Completeness establishes coverage only, not values, associations or the winning result. An incomplete comparison cannot establish a whole-list winner or absence. An absence claim needs a complete collection identified by quoted context and every member's identity and relevant fields. Check every member for a match and preserve the collection's bounded scope. Observed page titles provide identity context, not missing field evidence. Return yes only if every part of the requested output is stated and evidenced by its own cited sources. For a criterion naming several fields, check that the answer explicitly reports each one; other fields passing cannot cover an omitted field. A collection with no matches supports an absence only when the answer explicitly reports that bounded absence. Every factual assertion in every selected claim must also be supported, including extra details the user did not request. One supported value cannot excuse another unsupported value in the same claim. A subjective recommendation may rest on a quoted property. A factual comparative advantage, including highest, lowest or best on a measured property, requires all compared operands in that claim's own citations. Quotes cited only by another claim cannot supply missing operands or support. Preserve uncertainty and explain failures."
    )
}

pub(super) fn removed(requirements: &str, remaining: &str, claim_text: &str) -> String {
    format!(
        "{UNTRUSTED}\n\n# Requirements\n{requirements}\n\n# Remaining answer\n{remaining}\n\n# Removed claim\n{claim_text}\n\nDoes removing this claim leave any requested output missing from the remaining answer? Check each requested field for each requested entity separately. The removed claim is not evidence and need not be true. Judge whether its subject still needs an answer. An optional detail or an output already stated elsewhere does not count as missing."
    )
}
